#include <stdio.h>
#include <string.h>

/* 朴素字符串匹配: 在文本 T 中查找模式 P 的所有出现位置, 最坏 O(n*m) */
void naive_match(const char *T, const char *P) {
    int n = (int)strlen(T), m = (int)strlen(P);
    int cnt = 0;
    for (int s = 0; s + m <= n; s++) {       /* 对齐位置 0..n-m */
        int j = 0;
        while (j < m && T[s + j] == P[j]) j++;  /* 逐位比较, 失配即停 */
        if (j == m) {                        /* 全部匹配 */
            printf("匹配位置: %d\n", s);
            cnt++;
        }
    }
    printf("共 %d 处匹配\n", cnt);
}

int main(void) {
    char T[1000], P[100];
    printf("请输入文本 T: ");
    scanf("%s", T);
    printf("请输入模式 P: ");
    scanf("%s", P);
    if (strlen(P) == 0 || strlen(P) > strlen(T)) {
        printf("模式为空或比文本长, 无匹配!\n");
        return 0;
    }
    naive_match(T, P);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define BASE 131
#define MOD 1000000007

/* 快速幂: 计算 BASE^m mod MOD(预计算 B^(m-1)) */
long long powmod(int m) {
    long long r = 1, b = BASE;
    while (m > 0) {
        if (m & 1) r = r * b % MOD;
        b = b * b % MOD;
        m >>= 1;
    }
    return r;
}

/* Rabin-Karp: 滚动哈希匹配, 期望 O(n+m) */
void rk_match(const char *T, const char *P) {
    int n = (int)strlen(T), m = (int)strlen(P);
    if (m > n) { printf("无匹配\n"); return; }
    long long hp = 0, ht = 0;
    for (int i = 0; i < m; i++) {            /* 模式哈希与首窗口哈希 */
        hp = (hp * BASE + P[i]) % MOD;
        ht = (ht * BASE + T[i]) % MOD;
    }
    long long pow = powmod(m - 1);           /* B^(m-1) 预计算 */
    int cnt = 0;
    for (int s = 0; s + m <= n; s++) {
        if (hp == ht) {                      /* 哈希相等才逐位确认(防碰撞) */
            int ok = 1;
            for (int j = 0; j < m; j++)
                if (T[s + j] != P[j]) { ok = 0; break; }
            if (ok) { printf("匹配位置: %d\n", s); cnt++; }
        }
        if (s + m < n) {                     /* 滚动: 去 T[s], 加 T[s+m] */
            ht = ((ht - (long long)T[s] * pow % MOD + MOD) % MOD * BASE + T[s + m]) % MOD;
        }
    }
    printf("共 %d 处匹配\n", cnt);
}

int main(void) {
    char T[1000], P[100];
    printf("请输入文本 T: ");
    scanf("%s", T);
    printf("请输入模式 P: ");
    scanf("%s", P);
    if (strlen(P) == 0) { printf("模式为空!\n"); return 0; }
    rk_match(T, P);
    return 0;
}

#include <stdio.h>
#include <string.h>

/* 前缀函数: pi[i] = P[0..i] 的最长真边界长度, 均摊 O(m) */
void build_pi(const char *P, int pi[], int m) {
    pi[0] = 0;
    for (int i = 1; i < m; i++) {
        int j = pi[i - 1];
        while (j > 0 && P[i] != P[j]) j = pi[j - 1];   /* 沿边界链回退 */
        if (P[i] == P[j]) j++;
        pi[i] = j;
    }
}

/* KMP 匹配: 文本指针 i 不回退, 失配跳转 j=pi[j-1], O(n+m) */
void kmp_match(const char *T, const char *P) {
    int n = (int)strlen(T), m = (int)strlen(P);
    int pi[100];
    build_pi(P, pi, m);
    int j = 0, cnt = 0;                    /* j: 已匹配的模式前缀长度 */
    for (int i = 0; i < n; i++) {
        while (j > 0 && T[i] != P[j]) j = pi[j - 1];   /* 失配跳转 */
        if (T[i] == P[j]) j++;
        if (j == m) {                      /* 完整匹配 */
            printf("匹配位置: %d\n", i - m + 1);
            j = pi[j - 1];                 /* 继续找重叠匹配 */
            cnt++;
        }
    }
    printf("共 %d 处匹配\n", cnt);
}

int main(void) {
    char T[1000], P[100];
    printf("请输入文本 T: ");
    scanf("%s", T);
    printf("请输入模式 P: ");
    scanf("%s", P);
    if (strlen(P) == 0 || strlen(P) > strlen(T)) {
        printf("无匹配\n");
        return 0;
    }
    kmp_match(T, P);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define ALPHA 256

/* 坏字符表: last[c] = c 在 P 中最右出现位置(未出现为 -1) */
void build_bc(const char *P, int m, int bc[]) {
    for (int c = 0; c < ALPHA; c++) bc[c] = -1;
    for (int j = 0; j < m; j++) bc[(unsigned char)P[j]] = j;
}

/* 好后缀表: gs[j] = 失配于位置 j 时至少移动多少(保证 ≥1) */
void build_gs(const char *P, int m, int gs[]) {
    int suff[100];
    suff[m - 1] = m;
    for (int i = m - 2; i >= 0; i--) {          /* suff[i]: P[0..i] 与 P 后缀的最大公共后缀长 */
        int j = i;
        while (j >= 0 && P[j] == P[m - 1 - (i - j)]) j--;
        suff[i] = i - j;
    }
    for (int i = 0; i < m; i++) gs[i] = m;
    int j = 0;
    for (int i = m - 1; i >= 0; i--)            /* 情形2: 好后缀的后缀是模式前缀 */
        if (suff[i] == i + 1)
            for (; j < m - 1 - i; j++)
                if (gs[j] == m) gs[j] = m - 1 - i;
    for (int i = 0; i < m - 1; i++)             /* 情形1: 好后缀在模式中早于当前出现 */
        gs[m - 1 - suff[i]] = m - 1 - i;
}

void bm_match(const char *T, const char *P) {
    int n = (int)strlen(T), m = (int)strlen(P);
    int bc[ALPHA], gs[100];
    build_bc(P, m, bc);
    build_gs(P, m, gs);
    int s = 0, cnt = 0;
    while (s <= n - m) {
        int j = m - 1;
        while (j >= 0 && P[j] == T[s + j]) j--;   /* 从右向左比较 */
        if (j < 0) {                              /* 完全匹配 */
            printf("匹配位置: %d\n", s);
            s += gs[0];                           /* 好后缀移动(≥1) */
            cnt++;
        } else {
            int b = j - bc[(unsigned char)T[s + j]];  /* 坏字符规则 */
            int g = gs[j];                            /* 好后缀规则 */
            s += (b > g ? b : g);                     /* 取较大, 保证 ≥1 且安全 */
        }
    }
    printf("共 %d 处匹配\n", cnt);
}

int main(void) {
    char T[1000], P[100];
    printf("请输入文本 T: ");
    scanf("%s", T);
    printf("请输入模式 P: ");
    scanf("%s", P);
    if (strlen(P) == 0 || strlen(P) > strlen(T)) { printf("无匹配\n"); return 0; }
    bm_match(T, P);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHA 26

/* 字典树结点: 26 个孩子 + 结束标记 + 经过该结点的单词数 */
typedef struct Node {
    struct Node *child[ALPHA];
    int is_end;
    int cnt;
} Node;

Node *new_node(void) {
    return (Node *)calloc(1, sizeof(Node));
}

/* 插入单词: O(|s|), 沿途结点 cnt 加 1 */
void insert(Node *root, const char *s) {
    Node *p = root;
    for (int i = 0; s[i]; i++) {
        int c = s[i] - 'a';
        if (!p->child[c]) p->child[c] = new_node();
        p = p->child[c];
        p->cnt++;
    }
    p->is_end = 1;
}

/* 查询单词是否存在: O(|s|) */
int search(Node *root, const char *s) {
    Node *p = root;
    for (int i = 0; s[i]; i++) {
        int c = s[i] - 'a';
        if (!p->child[c]) return 0;
        p = p->child[c];
    }
    return p->is_end;
}

/* 前缀计数: O(|s|) */
int count_prefix(Node *root, const char *s) {
    Node *p = root;
    for (int i = 0; s[i]; i++) {
        int c = s[i] - 'a';
        if (!p->child[c]) return 0;
        p = p->child[c];
    }
    return p->cnt;
}

int main(void) {
    int n, m;
    char word[50], op;
    printf("请输入单词数 n: ");
    if (scanf("%d", &n) != 1 || n < 1) return 1;
    Node *root = new_node();
    for (int i = 0; i < n; i++) { scanf("%s", word); insert(root, word); }
    printf("请输入查询数 m: ");
    scanf("%d", &m);
    for (int i = 0; i < m; i++) {
        scanf(" %c %s", &op, word);
        if (op == '1')
            printf("%s %s\n", word, search(root, word) ? "存在" : "不存在");
        else
            printf("前缀 %s 的单词数: %d\n", word, count_prefix(root, word));
    }
    return 0;
}

# 字典树(Trie): 插入 O(|s|), 查询 O(|s|), 前缀计数 O(|s|)
class TrieNode:
    def __init__(self):
        self.child = {}
        self.is_end = False
        self.cnt = 0              # 经过该结点的单词数(前缀计数用)

def insert(root, s):
    p = root
    for ch in s:
        if ch not in p.child:
            p.child[ch] = TrieNode()
        p = p.child[ch]
        p.cnt += 1                # 沿途计数
    p.is_end = True

def search(root, s):
    p = root
    for ch in s:
        if ch not in p.child:
            return False
        p = p.child[ch]
    return p.is_end

def count_prefix(root, s):
    p = root
    for ch in s:
        if ch not in p.child:
            return 0
        p = p.child[ch]
    return p.cnt

root = TrieNode()
n = int(input("请输入单词数 n: "))
for _ in range(n):
    insert(root, input().strip())
m = int(input("请输入查询数 m: "))
for _ in range(m):
    kind, s = input().split()
    if kind == "1":
        print(f"{s} {'存在' if search(root, s) else '不存在'}")
    else:
        print(f"前缀 {s} 的单词数: {count_prefix(root, s)}")
